			"STALKER" => CurrentLanguage.enemyNames.enemyname_stalker,
			"VERY CANCEROUS RODENT" => CurrentLanguage.enemyNames.enemyname_boss_veryCancerousRodent,
			"CANCEROUS RODENT" => CurrentLanguage.enemyNames.enemyname_boss_cancerousRodent,
			"FERRYMAN" => CurrentLanguage.enemyNames.enemyname_ferryman,
