		{
			"LESSER HUSK" => CurrentLanguage.enemyNames.enemyname_type_lesserHusk,
			"GREATER HUSK" => CurrentLanguage.enemyNames.enemyname_type_greaterHusk,
			"SUPREME HUSK" => CurrentLanguage.enemyNames.enemyname_type_supremeHusk,
			"LESSER DEMON" => CurrentLanguage.enemyNames.enemyname_type_lesserDemon,
			"GREATER DEMON" => CurrentLanguage.enemyNames.enemyname_type_greaterDemon,
			"SUPREME DEMON" => CurrentLanguage.enemyNames.enemyname_type_supremeDemon,
			"LESSER MACHINE" => CurrentLanguage.enemyNames.enemyname_type_lesserMachine,
			"GREATER MACHINE" => CurrentLanguage.enemyNames.enemyname_type_greaterMachine,
			"SUPREME MACHINE" => CurrentLanguage.enemyNames.enemyname_type_supremeMachine,
			"LESSER ANGEL" => CurrentLanguage.enemyNames.enemyname_type_lesserAngel,
			"GREATER ANGEL" => CurrentLanguage.enemyNames.enemyname_type_greaterAngel,
			"SUPREME ANGEL" => CurrentLanguage.enemyNames.enemyname_type_supremeAngel,
			"???" => "???",
